```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, c.span_name, s.service_name AS callee, count(*) AS n, round(approx_quantile(c.duration,0.5)/1e6,1) AS caller_span_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) AS callee_server_p50_ms, round(approx_quantile(c.duration,0.95)/1e6,1) AS caller_span_p95_ms, round(approx_quantile(s.duration,0.95)/1e6,2) AS callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'search' AND c.span_name = 'rate.Rate/GetRates' AND s.service_name = 'rate' GROUP BY ALL",
          "claim": "search's outgoing rate.Rate/GetRates spans take about 1.5s p50 while rate's server spans stay around 0.8ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, c.span_name, s.service_name AS callee, count(*) AS n, round(approx_quantile(c.duration,0.5)/1e6,2) AS caller_span_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) AS callee_server_p50_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'search' AND c.span_name = 'rate.Rate/GetRates' AND s.service_name = 'rate' GROUP BY ALL",
          "claim": "In the normal period the same search-to-rate call spans take about 0.5ms p50 with rate server near 0.1ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, round(approx_quantile(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name = 'search' AND span_name = 'search.Search/Nearby' AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "search's own Search/Nearby server spans have p95 near 2.9s, inherited from the slow rate calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, c.span_name, s.service_name AS callee, count(*) AS n, round(approx_quantile(c.duration,0.95)/1e6,1) AS frontend_client_p95_ms, round(approx_quantile(s.duration,0.95)/1e6,1) AS search_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'frontend' AND c.span_name = 'search.Search/Nearby' AND s.service_name = 'search' GROUP BY ALL",
          "claim": "frontend's search.Search/Nearby calls to search show p95 near 2.9s, matching search's server time, so the delay passes through to the user-facing frontend."
        }
      ]
    }
  ]
}
```

